def monotonic(l):
    if isinstance(l, list):
        # Check monotonic non-decreasing or non-increasing allowing duplicates
        def non_decreasing(lst):
            return all(x <= y for x, y in zip(lst, lst[1:]))

        def non_increasing(lst):
            return all(x >= y for x, y in zip(lst, lst[1:]))

        # No loops allowed, so replace all with recursion or comprehension?
        # The prompt prohibits loops and in-built sorting, but comprehension is allowed as it's not a loop statement.
        # However, to be safe, implement recursion for all checks.

        def check_non_decreasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] <= lst[1] and check_non_decreasing(lst[1:])

        def check_non_increasing(lst):
            if len(lst) < 2:
                return True
            return lst[0] >= lst[1] and check_non_increasing(lst[1:])

        return check_non_decreasing(l) or check_non_increasing(l)

    elif isinstance(l, str):
        # For strings: return True if strictly increasing or strictly decreasing with no duplicates,
        # else False. Also return the original string if True.

