def next_smallest_palindrome(n: int) -> int:
    # For single digit inputs, return the next integer palindrome (next integer)
    if 0 <= n <= 8:
        return n + 1
    if n == 9:
        return 11

    s = str(n)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If number is palindrome and > 9, find next smallest palindrome greater than n
    # Approach:
    # 1. Construct palindrome by mirroring left half to right half
    # 2. If palindrome <= n, increment the middle part and mirror again
    # 3. Return the palindrome as int

    half = length // 2
    odd = (length % 2) != 0

    left = s[:half]
    mid = s[half] if odd else ''
    right = s[half+1:] if odd else s[half:]

    # Build palindrome by mirroring left and mid
    if odd:
        palindrome = left + mid + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) > n:
        return int(palindrome)

    # Increment the middle part and mirror again
    if odd:
        # Increment middle digit and handle carry if needed
        mid_int = int(mid) + 1
        if mid_int <= 9:
            palindrome = left + str(mid_int) + left[::-1]
