def find_solution(a: int, b: int, n: int):
    # We want to find non-negative integers x,y such that a*x + b*y = n.
    # If no such pair exists, return "No solution".
    # We try all x from 0 to n//a (if a!=0), else handle separately.

    if a == 0 and b == 0:
        # Equation 0*x + 0*y = n: only possible if n==0
        return (0, 0) if n == 0 else "No solution"

    if a == 0:
        # Equation reduces to b*y = n
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return "No solution"

    if b == 0:
        # Equation reduces to a*x = n
        if a != 0 and n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return "No solution"

    max_x = n // a if a > 0 else 0
    if a < 0:
        # if a<0, max_x should be 0 because x>=0
        max_x = 0

    for x in range(max_x + 1):
        rem = n - a * x
        if rem < 0:
            # because b*y = rem and y>=0, rem must be >=0
            continue
        if b != 0 and rem % b == 0:
            y = rem // b
            if y >= 0:
                return (x, y)
    return "No solution"

