def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If number <= 0, no smaller palindrome positive number exists
    if num <= 0:
        return -1  # or 0 or some indication no smaller palindrome exists

    # Generate palindrome by mirroring left half
    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    # Start from num-1 and go down until palindrome found
    # To optimize, try to build palindrome from left half and decrease

    odd_length = (length % 2 != 0)
    left_half_len = (length + 1) // 2  # includes middle if odd length

    left_half = s[:left_half_len]

    # Try palindrome from left half mirrored
    candidate = make_palindrome(left_half, odd_length)
    if candidate >= num:
        # Need to decrease left half and try again
        left_num = int(left_half) - 1
        if left_num == 0:
            # This means palindrome like 1000... after decrement becomes smaller length palindrome
            # e.g. input 10001 -> next smaller palindrome is 9999
            return int("9" * (length - 1))
        left_half = str(left_num)
        if len(left_half) < left_half_len:
            # length reduced, so return all 9's of smaller length palindrome
            return int("9" * (length - 1))
        candidate = make_palindrome(left_half, odd_length)

    # If candidate < num and palindrome, done
    if candidate < num:
        return candidate

    # fallback linear search downwards (should not reach here for normal cases)
    for candidate in range(num - 1, 0, -1):
        if is_palindrome(str(candidate)):
            return candidate

    return -1  # no smaller palindrome found (should not happen for positive input)


