def get_total_number_of_sequences(n: int, m: int) -> int:
    # dp[pos][val] = number of sequences of length pos ending with val
    # pos ranges from 1 to n (1-based for convenience)
    # val ranges from 1 to m

    if n == 1:
        # Any element from 1 to m is valid as sequence of length 1
        return m

    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Initialize for position 1: any starting element from 1 to m
    for val in range(1, m+1):
        dp[1][val] = 1

    for pos in range(2, n+1):
        for val in range(1, m+1):
            # previous element must be <= val//2 (since val >= 2 * prev)
            prev_max = val // 2
            if prev_max >= 1:
                # sum dp[pos-1][prev_val] for prev_val in [1..prev_max]
                # to improve speed, we can precompute prefix sums
                dp[pos][val] = sum(dp[pos-1][1:prev_max+1])

    # total sequences of length n, sum over all ending values
    return sum(dp[n][1:])

