def find_Max(arr: list[int], low: int, high: int) -> int:
    # If the array is not rotated (sorted array), the last element is the maximum
    if high < low:
        return arr[high]
    # If there is only one element left
    if high == low:
        return arr[low]

    mid = (low + high) // 2

    # Check if mid element is greater than its next element
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid element is smaller than its previous element
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide to go to left half or right half
    if arr[low] >= arr[mid]:
        return find_Max(arr, low, mid - 1)
    return find_Max(arr, mid + 1, high)

