def get_total_number_of_sequences(n: int, m: int) -> int:
    """
    Returns the number of ordered sequences of length n,
    with each element an integer in [1, m],
    where each subsequent element is at least double the previous element.
    """

    # Cache for memoization: key=(pos, prev), value=number of sequences
    from functools import lru_cache

    @lru_cache(None)
    def count(pos: int, prev: int) -> int:
        if pos == n:
            return 1
        total = 0
        # For the first element, prev=0 means no restriction (start from 1)
        start = max(1, 2 * prev) if prev > 0 else 1
        for val in range(start, m + 1):
            total += count(pos + 1, val)
        return total

    return count(0, 0)

