    # We want nonnegative integers x,y such that a*x + b*y = n
    # Try all x from 0 up to n//a (if a > 0)
    # For each x, check if (n - a*x) is divisible by b and nonnegative
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        # Then b*y = n
        if b != 0 and n % b == 0 and n // b >= 0:
            return (0, n // b)
