            return (n // a, 0)
        else:
            return None

    max_x = n // a if a > 0 else 0
    for x in range(max_x + 1):
        remainder = n - a * x
        if remainder < 0:
            break
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
