def min_flip_to_make_string_alternate(s: str) -> int:
    # Count flips needed to make string alternate starting with '0'
    flips_start_0 = 0
    for i, ch in enumerate(s):
        expected_char = '0' if i % 2 == 0 else '1'
        if ch != expected_char:
            flips_start_0 += 1

    # Count flips needed to make string alternate starting with '1'
    flips_start_1 = 0
    for i, ch in enumerate(s):
        expected_char = '1' if i % 2 == 0 else '0'
        if ch != expected_char:
            flips_start_1 += 1

    # Return minimum flips of the two possible alternating sequences
    return min(flips_start_0, flips_start_1)

def repeat_tuples(t: tuple, n: int) -> tuple:
    if n < 0:
        return ()
    return t * n

def permute_string(s: str) -> None:
    def backtrack(path, used):
        if len(path) == len(s):
            print(''.join(path))
            return
        for i in range(len(s)):
            if not used[i]:
                used[i] = True
                path.append(s[i])
                backtrack(path, used)
                path.pop()
                used[i] = False

    used = [False] * len(s)
    backtrack([], used)

def highest_Power_of_2(n: int) -> int:
    if n == 0:
        return 0
    power = 1
    while power <= n:
        power <<= 1
    return power >> 1

