def find_remainder(arr, n):
    result = 1
    for x in arr:
        result = (result * x) % n
    return result

def find_Max(arr):
    if not arr:
        return None  # No maximum in empty array
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] > arr[high]:
            low = mid + 1
        else:
            high = mid
    # low is index of minimum element, max is element before it (or last if min at 0)
    return arr[low - 1] if low > 0 else arr[-1]

from collections import Counter

def check_subset(t1: tuple, t2: tuple) -> bool:
    c1 = Counter(t1)
    c2 = Counter(t2)
    for elem, count in c1.items():
        if c2[elem] < count:
            return False
    return True

def recur_gcd(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    if b == 0:
        return a
    return recur_gcd(b, a % b)

def str_to_tuple(s: str) -> tuple[int, ...]:
    # The input string is expected to have integers separated by commas and a space after each comma,
