import re

def capital_words_spaces(s: str) -> str:
    # Insert a space before each capital letter that is preceded by a lowercase letter or another capital letter (not at start)
    return re.sub(r'(?<!^)(?=[A-Z])', ' ', s)

def sum_column(lst: list[list[int]], col: int) -> int:
    total = 0
    for sublist in lst:
        if len(sublist) > col:
            total += sublist[col]
    return total

def length_Of_Last_Word(s: str) -> int:
